function numPermsDISequence(s) {
  const MOD = 1_000_000_007;
  const n = s.length;
  const dp = Array.from({ length: n + 1 }, () => new Array(n + 1).fill(0));
  dp[0][0] = 1;

  for (let i = 1; i <= n; i++) {
    const prefix = new Array(i + 1).fill(0);
    for (let k = 0; k < i; k++) {
      prefix[k + 1] = (prefix[k] + dp[i - 1][k]) % MOD;
    }
    for (let j = 0; j <= i; j++) {
      if (s[i - 1] === 'I') {
        dp[i][j] = prefix[j];
      } else {
        dp[i][j] = (prefix[i] - prefix[j] + MOD) % MOD;
      }
    }
  }

  let total = 0;
  for (let j = 0; j <= n; j++) {
    total = (total + dp[n][j]) % MOD;
  }
  return total;
}

