function numPermsDISequence(s) {
  const n = s.length;
  const used = new Array(n + 1).fill(false);
  let count = 0;
  const place = (pos, last) => {
    if (pos === n + 1) { count++; return; }
    for (let v = 0; v <= n; v++) {
      if (used[v]) continue;
      if (pos > 0 && s[pos - 1] === 'D' && !(last > v)) continue;
      if (pos > 0 && s[pos - 1] === 'I' && !(last < v)) continue;
      used[v] = true;
      place(pos + 1, v);
      used[v] = false;
    }
  };
  place(0, -1);
  return count % 1000000007;
}

