function generate(rand, size) {
  const n = size === 'large' ? 150 + Math.floor(rand() * 51) : 1 + Math.floor(rand() * 7);
  const bias = rand();
  let s = '';
  for (let i = 0; i < n; i++) s += rand() < bias ? 'D' : 'I';
  return [s];
}
